insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'fgcu-collectives'), 1, 'yes_with_conditions', 'FGCU''s page says FGCU may not give financial, physical or human resources or other indirect financial support to an NIL entity such as a collective. In 2023 FGCU Athletics announced SWFL Flight Crew as a third-party collective.', 'Both statements predate the House settlement. Current status of the collective was not confirmed. Published before the July 2025 rule changes or undated. Confirm with the school that it still applies.', 'FGCU Name, Image, Likeness page and 2023 news release', 'needs_verification', 'PENDING_INSTITUTION_CONFIRMATION', 'raw_source_text', 'The school published this before the July 2025 rule changes, or on an undated page. It has not been confirmed as current.', 'CHECK_FIRST', 'FGCU says it cannot fund a collective.');
